@import "@fontsource-variable/jost";
@import "@fontsource-variable/jost/wght-italic.css";

/* Light (faithful): the parchment page #e7dbc3, flag navy #1f3b64 text and hairlines, signal
   red #bb2024 buttons, a deeper cream #dfd0b0 behind media, navy bands (secondary). */
:root {
  --background: oklch(0.895 0.035 85);
  --foreground: oklch(0.353 0.079 258);
  --card: oklch(0.862 0.046 86);
  --card-foreground: oklch(0.353 0.079 258);
  --popover: oklch(0.895 0.035 85);
  --popover-foreground: oklch(0.353 0.079 258);
  --primary: oklch(0.512 0.189 26);
  --primary-foreground: oklch(0.895 0.035 85);
  --secondary: oklch(0.353 0.079 258);
  --secondary-foreground: oklch(0.895 0.035 85);
  --muted: oklch(0.862 0.046 86);
  --muted-foreground: oklch(0.353 0.079 258 / 0.72);
  --accent: oklch(0.862 0.046 86);
  --accent-foreground: oklch(0.353 0.079 258);
  --destructive: oklch(0.512 0.189 26);
  --destructive-foreground: oklch(0.895 0.035 85);
  --border: oklch(0.353 0.079 258);
  --input: oklch(0.353 0.079 258);
  --ring: oklch(0.512 0.189 26);
  --highlight: oklch(0.512 0.189 26);
  --highlight-foreground: oklch(0.895 0.035 85);
  --glow: oklch(0.655 0.106 64);
  --chart-1: oklch(0.353 0.079 258);
  --chart-2: oklch(0.512 0.189 26);
  --chart-3: oklch(0.655 0.106 64);
  --chart-4: oklch(0.426 0.117 252);
  --chart-5: oklch(0.213 0 0);
  --sidebar: oklch(0.862 0.046 86);
  --sidebar-foreground: oklch(0.353 0.079 258);
  --sidebar-primary: oklch(0.512 0.189 26);
  --sidebar-primary-foreground: oklch(0.895 0.035 85);
  --sidebar-accent: oklch(0.895 0.035 85);
  --sidebar-accent-foreground: oklch(0.353 0.079 258);
  --sidebar-border: oklch(0.353 0.079 258);
  --sidebar-ring: oklch(0.512 0.189 26);

  --typeface-body: "Jost Variable", "Futura", "Century Gothic", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Jost Variable", "Futura", "Century Gothic", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.25rem;
  --page-width: 90rem;
  --page-gutter: clamp(1.125rem, 5.143vw - 0.129rem, 4.5rem);
  --section-y: clamp(3.125rem, 2.06rem + 2.86vw, 5.5rem);
}

/* Dark: the navy bands of the light page (cream text, cream 2px outlines, the ink #191919
   notice card, red buttons) and the dark-mode page, an ink-navy #14243d under navy bands. */
.dark {
  --background: oklch(0.26 0.052 259);
  --foreground: oklch(0.895 0.035 85);
  --card: oklch(0.213 0 0);
  --card-foreground: oklch(0.895 0.035 85);
  --popover: oklch(0.353 0.079 258);
  --popover-foreground: oklch(0.895 0.035 85);
  --primary: oklch(0.512 0.189 26);
  --primary-foreground: oklch(0.895 0.035 85);
  --secondary: oklch(0.353 0.079 258);
  --secondary-foreground: oklch(0.895 0.035 85);
  --muted: oklch(0.415 0.086 258);
  --muted-foreground: oklch(0.895 0.035 85 / 0.7);
  --accent: oklch(0.415 0.086 258);
  --accent-foreground: oklch(0.895 0.035 85);
  --destructive: oklch(0.58 0.19 26);
  --destructive-foreground: oklch(0.895 0.035 85);
  --border: oklch(0.895 0.035 85);
  --input: oklch(0.895 0.035 85);
  --ring: oklch(0.895 0.035 85);
  --highlight: oklch(0.52 0.12 250);
  --highlight-foreground: oklch(0.895 0.035 85);
  --glow: oklch(0.655 0.106 64);
  --chart-1: oklch(0.895 0.035 85);
  --chart-2: oklch(0.512 0.189 26);
  --chart-3: oklch(0.655 0.106 64);
  --chart-4: oklch(0.52 0.12 250);
  --chart-5: oklch(0.415 0.086 258);
  --sidebar: oklch(0.26 0.052 259);
  --sidebar-foreground: oklch(0.895 0.035 85);
  --sidebar-primary: oklch(0.512 0.189 26);
  --sidebar-primary-foreground: oklch(0.895 0.035 85);
  --sidebar-accent: oklch(0.353 0.079 258);
  --sidebar-accent-foreground: oklch(0.895 0.035 85);
  --sidebar-border: oklch(0.415 0.086 258);
  --sidebar-ring: oklch(0.895 0.035 85);
}
